import re, fitz
from pathlib import Path

patterns = [re.compile(r'arXiv[:\s]\S+'), re.compile(r'\bdoi\b', re.I), re.compile(r'accepted', re.I), re.compile(r'conference', re.I), re.compile(r'proceedings', re.I), re.compile(r'workshop', re.I)]

for p in [Path(f'/root/paper{i}.pdf') for i in range(1,4)]:
    doc = fitz.open(p)
    print('===', p)
    for i, page in enumerate(doc):
        text = page.get_text()
        if not text.strip():
            continue
        for line in text.splitlines():
            for pat in patterns:
                if pat.search(line):
                    print(f'page {i+1}: {line.strip()}')
                    break
    doc.close()
    print()
